      "view_ids": ["tyQaMS8skCpsOJ0wRHbang"],
      "status": "inferred",
      "description": "Línea de coronación horizontal simple al cierre del nivel superior; sin frontón, volutas, dentículos ni cornisas escalonadas."
    }
